import { MAPS } from '/home/lane/AIArchives/archives/neonstrike/app/public/js/maps.js';

const CLEAR = 1.0; // required clearance from solids

function boxesAt(boxes, y0, y1) {
  return boxes.filter(b => b[6] !== 4 && b[6] !== 5 && b[4] > y0 && b[1] < y1);
}
function pointDistToBox2D(x, z, b) {
  const dx = Math.max(b[0] - x, 0, x - b[3]);
  const dz = Math.max(b[2] - z, 0, z - b[5]);
  return Math.hypot(dx, dz);
}
function segIntersectsBox2D(x1, z1, x2, z2, b) {
  // Liang-Barsky against [b0,b3]x[b2,b5]
  let t0 = 0, t1 = 1;
  const dx = x2 - x1, dz = z2 - z1;
  const p = [-dx, dx, -dz, dz];
  const q = [x1 - b[0], b[3] - x1, z1 - b[2], b[5] - z1];
  for (let i = 0; i < 4; i++) {
    if (p[i] === 0) { if (q[i] < 0) return false; }
    else {
      const r = q[i] / p[i];
      if (p[i] < 0) { if (r > t1) return false; if (r > t0) t0 = r; }
      else { if (r < t0) return false; if (r < t1) t1 = r; }
    }
  }
  return true;
}
// does a point stand on a surface (box top) at given floor height set?
function standsOn(boxes, x, z) {
  let top = -Infinity;
  for (const b of boxes) {
    if (b[6] === 4 || b[6] === 5) continue;
    if (x >= b[0] && x <= b[3] && z >= b[2] && z <= b[5]) top = Math.max(top, b[4]);
  }
  return top; // -Infinity = over nothing
}

for (const [id, m] of Object.entries(MAPS)) {
  console.log(`\n=== ${id} (${m.name}) ===`);
  console.log(`boxes: ${m.BOXES.length}  lights: ${m.LIGHTS.length}  waypoints: ${m.WAYPOINTS.length}  edges: ${m.WAYPOINT_EDGES.length}`);
  let ok = true;

  // last light = muzzle slot
  const last = m.LIGHTS[m.LIGHTS.length - 1];
  if (JSON.stringify(last) !== JSON.stringify([0, -100, 0, 1, 0.85, 0.5, 0])) {
    console.log('FAIL: last light is not muzzle slot', last); ok = false;
  }

  // body solids for clearance: y range [0,1.8] (canopy: also street band)
  const bodySolids = boxesAt(m.BOXES, 0.0, 1.8);
  const pts = [];
  pts.push(['PLAYER_SPAWN', m.PLAYER_SPAWN.x, m.PLAYER_SPAWN.z]);
  m.BOT_SPAWNS.forEach((s, i) => pts.push([`BOT_SPAWN[${i}]`, s.x, s.z]));
  m.DM_SPAWNS.forEach((s, i) => pts.push([`DM_SPAWN[${i}]`, s.x, s.z]));
  m.WAYPOINTS.forEach((s, i) => pts.push([`WAYPOINT[${i}]`, s.x, s.z]));

  let clearFails = 0;
  for (const [label, x, z] of pts) {
    for (const b of bodySolids) {
      const d = pointDistToBox2D(x, z, b);
      if (d < CLEAR) {
        console.log(`FAIL clearance: ${label} (${x},${z}) dist ${d.toFixed(2)} to box [${b}]`);
        clearFails++; ok = false;
      }
    }
    if (id === 'canopy') {
      const top = standsOn(m.BOXES, x, z);
      if (!(top === 0 || top === -2)) {
        console.log(`FAIL surface: ${label} (${x},${z}) stands on top=${top}`);
        ok = false;
      }
    }
  }
  console.log(`spawn/waypoint clearance: ${clearFails === 0 ? 'PASS' : clearFails + ' fails'} (${pts.length} points checked)`);

  // connectivity
  const n = m.WAYPOINTS.length;
  const adj = Array.from({ length: n }, () => []);
  for (const [a, b] of m.WAYPOINT_EDGES) { adj[a].push(b); adj[b].push(a); }
  const seen = new Set([0]); const st = [0];
  while (st.length) { const v = st.pop(); for (const w of adj[v]) if (!seen.has(w)) { seen.add(w); st.push(w); } }
  console.log(`waypoint connectivity: ${seen.size === n ? 'PASS (single component)' : `FAIL ${seen.size}/${n} reachable`}`);
  if (seen.size !== n) ok = false;

  // edge LOS vs boxes overlapping y [0.5,1.5]
  const losSolids = boxesAt(m.BOXES, 0.5, 1.5);
  let losFails = 0;
  for (const [a, b] of m.WAYPOINT_EDGES) {
    const A = m.WAYPOINTS[a], B = m.WAYPOINTS[b];
    for (const box of losSolids) {
      if (segIntersectsBox2D(A.x, A.z, B.x, B.z, box)) {
        console.log(`FAIL LOS: edge ${a}-${b} crosses box [${box}]`);
        losFails++; ok = false;
      }
    }
  }
  console.log(`edge LOS: ${losFails === 0 ? `PASS (${m.WAYPOINT_EDGES.length} edges vs ${losSolids.length} solids)` : losFails + ' fails'}`);
  console.log(ok ? 'MAP OK' : 'MAP HAS FAILURES');
}
